 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, texture, color, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide, SRGBColorSpace } = ctx.THREE;

  const visual = config.intent?.visualSpec ?? config;
  const colors = visual?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const regionW = 512;
  const regionH = 320;
  const aspect = regionW / regionH;

  const group = new Group();
  group.name = config.id ?? 'features-title';

  // Engineered gradient sprite plane
  const planeGeo = new PlaneGeometry(aspect * 1.0, 1.0, 1, 1);
  const planeMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false
  });

  const inkNode = color(colors.ink);
  const surfaceNode = color(colors.surface);
  const gradNode = mix(inkNode, surfaceNode, uv().y);
  planeMat.colorNode = gradNode;

  const plane = new Mesh(planeGeo, planeMat);
  plane.name = 'title-sprite';
  group.add(plane);

  // Subtle ceramic grain overlay via .map node
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      tex.wrapS = ctx.THREE.RepeatWrapping;
      tex.wrapT = ctx.THREE.RepeatWrapping;
      const baseUV = uv();
      planeMat.map = texture(tex).uv(baseUV);
      planeMat.needsUpdate = true;
    });
  }

  // Headline text rendered through the font atlas
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  if (headlineItem) {
    const textObj = ctx.fontAtlas.createText(String(headlineItem.text ?? 'Features'), {
      fontSize: headlineItem.typography?.fontSize ?? 96,
      color: colors.paper,
      align: 'center'
    });
    textObj.name = 'title-text';
    textObj.position.z = 0.02;
    group.add(textObj);
  }

  // Billboarding toward the camera
  group.onBeforeRender = function (_renderer, _scene, camera) {
    group.quaternion.copy(camera.quaternion);
  };

  // Entrance motion: rise-in + weighted settle
  const entranceTl = gsap.timeline();
  group.position.y = 0.4;
  group.scale.setScalar(0);

  entranceTl.to(group.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out'
  }, 0);

  entranceTl.to(group.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.45,
    ease: 'power3.out'
  }, 0);

  entranceTl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.45,
    ease: 'power4.out'
  });

  // Single idle breathing motion (<=2%)
  const idleTl = gsap.to(group.position, {
    y: 0.015,
    duration: 2.2,
    yoyo: true,
    repeat: -1,
    ease: 'sine.inOut'
  });

  const timelines = [entranceTl, idleTl];

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());

    if (planeMat.map && planeMat.map.value) {
      // Dispose cached texture only if we are confident no other node reuses it.
      // Shared loader cache is safe to leave intact, so we release the local reference.
      planeMat.map = null;
    }

    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });

    if (group.parent) {
      group.parent.remove(group);
    }
  };

  return group;
}
